@property {ignore} ignore

@property {lookupSwiss} lookupSwiss  for E style swissNum based sturdyrefs
@property {makeSeqBlock} makeSeqBlock  to support various of E().where() usage patterns.
@property {makeFromActiveCapCert} makeFromActiveCapCert  for cert based sturdyrefs that allow for unforseen attenuated delegation
@property {asyncHelpers} getAsyncHelpers
*/

/*
@define getBootstrap
@return {any}
*/

/*
@define provideFor
@param {any} gift
@param {vatId} reciepent
@param {BigInt} nonce
@return {vine}
*/

/*
@define acceptFrom
@param {vatId} donor
@param {BigInt} nonce
@param {vine} vine
@return {any}
*/

/*
@define {any} vine
*/

/*
@define ignore
@param {vine} vine
@return {undefined}
*/

/*
@define lookupSwiss
@param {bigint} swissNum
@param {vine} vine
@return {any}
*/

/*
@define makeSeqBlock
@param {seqBlock} seqBlock
@param {Maybe<Map<any, any>>>} environ
@return {Function<any>}
*/

/*
@define makeFromActiveCapCert
@param {ActiveCapCert} cert
@return {Function<any>}
*/

/*
@define asyncHelpers
@property {awaitSomeArgsForMethod} awaitSomeArgsForMethod
@property {awaitSomeArgsForFunction} awaitSomeArgsForFunction
*/
```

provideFor and acceptFrom methods are part of the 3rd party handoff (see #12 for more information on that)
